/**
 * Shared Next/Image blur placeholders so photos paint instantly
 * (warm sand for product shots, dark bark for full-bleed heroes).
 */
export const BLUR_DARK =
  "data:image/jpeg;base64,";

export const BLUR_SAND =
  "data:image/jpeg;base64,";

export const blurDark = {
  placeholder: "blur" as const,
  blurDataURL: BLUR_DARK,
};

export const blurSand = {
  placeholder: "blur" as const,
  blurDataURL: BLUR_SAND,
};
